actions.script:
const L = (text) => ec.l10n.localize(text)
const pct = (value) => value == null ? '' : ec.l10n.format(Math.round(Number(String(value)) * 10) / 10, '#,##0.#') + '%'
managesMoney = !!ec.service.sync().name('ironstone.projects.BillingServices.check#Money').parameters({need: 'none'}).call()?.managesMoney
ec.message.clearErrors()
if (!basis) basis = 'billable'
projectRows = []; clientRows = []; projectRowsCount = 0; clientRowsCount = 0; rowsFound = false; hasChart = false; chartHtml = ''; chartTui = {t: 'text', text: ''}
projectOptions = []; clientOptions = []
billableValue = ''; costValue = ''; marginValue = ''; marginPctValue = ''; billedValue = ''; unbilledValue = ''; missingNote = ''
rangeText = L('All time')
const query = {fromDate: fromDate || '', thruDate: thruDate || '', clientPartyId: clientPartyId || '', rootWorkEffortId: rootWorkEffortId || '', basis: basis}
printUrl = '/apps/Projects/Reports/Profitability?renderMode=html-print&' + Object.entries(query).filter(([key, value]) => value).map(([key, value]) => key + '=' + encodeURIComponent(value)).join('&')
if (!managesMoney) return
const options = ec.service.sync().name('ironstone.projects.ReportServices.get#ReportOptions').call() || {}
ec.message.clearErrors()
projectOptions = Array.from(options.projectOptions || [])
clientOptions = Array.from(options.clientOptions || [])
const out = ec.service.sync().name('mantle.work.ProjectReportServices.get#ProjectProfitability').parameters({fromDate: fromDate || null, thruDate: thruDate || null,
    clientPartyId: clientPartyId || null, rootWorkEffortId: rootWorkEffortId || null, basis: basis}).call() || {}
ec.message.clearErrors()
const dayText = (day) => ec.l10n.format(ec.l10n.parseTimestamp(day + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'MMM d, yyyy')
if (out.fromDay || out.thruDay) rangeText = (out.fromDay ? dayText(out.fromDay) : L('The start')) + ' – ' + (out.thruDay ? dayText(out.thruDay) : L('today'))
const totals = out.totals || {}
const totalCurrency = totals.currencyUomId
const moneyIn = (value, currency) => value == null ? '' : (currency ? ec.l10n.formatCurrency(value, currency) : ec.l10n.format(Math.round(Number(String(value)) * 100) / 100, '#,##0.00'))
const rowOf = (row, currency, isTotal) => ({isTotal: isTotal, workEffortId: row.workEffortId || null, workEffortName: row.workEffortName || '',
    clientName: row.clientName || '', projectCount: row.projectCount ?? null,
    budgetText: row.budget ? moneyIn(row.budget, currency) : '', costText: moneyIn(row.cost, currency), valueText: moneyIn(row.billableValue, currency),
    billedText: moneyIn(row.billed, currency), unbilledText: moneyIn(row.unbilled, currency), marginText: moneyIn(row.margin, currency),
    marginPctText: pct(row.marginPercent), budgetUsedText: pct(row.budgetUsedPercent), negative: Number(row.margin || 0) < 0,
    noteText: [row.costMissingCount ? ec.resource.expand('${count} without a worker rate', '', {count: row.costMissingCount}) : '',
        row.valueMissingCount ? ec.resource.expand('${count} without a client rate', '', {count: row.valueMissingCount}) : '',
        row.mixedCurrency ? L('Several currencies') : ''].filter((part) => part).join('; ')})
const projects = Array.from(out.projectList || [])
projectRows = projects.map((row) => rowOf(row, row.currencyUomId, false))
rowsFound = projectRows.length > 0
if (rowsFound) projectRows.push(rowOf(Object.assign({}, totals, {workEffortName: L('Total'), clientName: ''}), totalCurrency, true))
projectRowsCount = projectRows.length
clientRows = Array.from(out.clientList || []).map((row) => rowOf(row, totalCurrency, false))
clientRowsCount = clientRows.length
const several = L('Several currencies')
const card = (value) => totals.mixedCurrency ? several : moneyIn(value || 0, totalCurrency || 'USD')
billableValue = card(totals.billableValue); costValue = card(totals.cost); marginValue = card(totals.margin)
billedValue = card(totals.billed); unbilledValue = card(totals.unbilled)
marginPctValue = totals.marginPercent == null ? '—' : pct(totals.marginPercent)
missingNote = totals.costMissingCount || totals.valueMissingCount ? ec.resource.expand('Entries without a rate count no money: ${cost} without a worker rate, ${value} billable without a client rate.', '',
    {cost: totals.costMissingCount || 0, value: totals.valueMissingCount || 0}) : ''
// the chart: billable value against cost by project, the margin as a line (the twelve largest by value)
const charted = projects.slice().sort((a, b) => Number(b.billableValue || 0) - Number(a.billableValue || 0)).slice(0, 12)
hasChart = charted.length > 0
const chart = hasChart ? ec.service.sync().name('ironstone.projects.ReportServices.get#ChartConfig').parameters({id: 'ProfitabilityChart', type: 'bar',
    labels: charted.map((row) => row.workEffortName), series: [
        {name: L('Billable value'), data: charted.map((row) => row.billableValue)},
        {name: L('Cost'), data: charted.map((row) => row.cost)},
        {name: L('Margin'), data: charted.map((row) => row.margin), kind: 'line'}],
    yTitle: totals.mixedCurrency ? L('Amount') : (totalCurrency || 'USD')}).call() || {} : {}
ec.message.clearErrors()
chartHtml = chart.html || ''
chartTui = chart.tui || {t: 'text', text: ''}
